contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address target, uint256 amount, address asset) public {
        // configure a flash governance so that a decision can be recorded
        c.configureFlashGovernance(asset, amount, 0, false);

        // attempt to create a pending flash governance decision
        // if the transfer succeeds and there is no existing decision, a pending decision exists
        bool reverted;
        try c.assertGovernanceApproved(sender, target, true) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read the pending decision via the public getter
        (uint256 storedAmount, uint256 unlockTime, address storedAsset, bool storedBurnable) = c.pendingFlashDecision(target, sender);

        // A pending decision is considered recorded if amount > 0 or asset != address(0)
        // (initial struct has amount 0 and asset 0)
        bool recorded = (storedAmount > 0 || storedAsset != address(0));

        if (!reverted) {
            // if not reverted, the decision must have been recorded with our configured asset and amount
            // unless there was already an existing decision with the same unlockTime check
            // We assert that no decision exists with a different amount/asset than what we configured, for our (target, sender)
            assert(storedAmount == amount && storedAsset == asset && storedBurnable == false);
        } else {
            // if reverted, either no decision was recorded, or the existing decision (if any) does not match our parameters
            // The general rule: the pending decision for (target, sender) cannot be in a state that claims to be ours but has wrong values.
            // More precisely, if a decision is recorded, it must have amount == amount and asset == asset from our configuration
            // because the only way to record it is through our call, which either succeeded or reverted due to existing decision.
            // However, if there was already a decision from a previous successful call, it could have different values only if
            // a previous call used different parameters. But we only call once, so no previous decision exists.
            // Actually, since the test runs only once and c is fresh, there is no previous decision.
            // So if reverted, the decision must not be recorded.
            assert(!recorded);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address target, uint256 amount, address asset, address other) public {
        require(other != sender, "different sender required");
        require(asset != address(0), "asset must be nonzero");
        require(amount > 0, "amount must be positive");

        c.configureFlashGovernance(asset, amount, 0, false);
        c.assertGovernanceApproved(sender, target, true);

        (uint256 storedAmount, uint256 storedUnlockTime, address storedAsset, bool storedBurnable) = c.pendingFlashDecision(target, sender);
        (uint256 otherAmount, uint256 otherUnlockTime, address otherAsset, bool otherBurnable) = c.pendingFlashDecision(target, other);

        c.assertGovernanceApproved(other, target, true);

        (uint256 afterOtherAmount, uint256 afterOtherUnlockTime, address afterOtherAsset, bool afterOtherBurnable) = c.pendingFlashDecision(target, sender);

        assert(
            storedAmount == amount &&
            storedAsset == asset &&
            storedBurnable == false &&
            otherAmount == 0 &&
            otherAsset == address(0) &&
            afterOtherAmount == storedAmount &&
            afterOtherAsset == storedAsset &&
            afterOtherBurnable == storedBurnable &&
            afterOtherUnlockTime == storedUnlockTime
        );
    }

    receive() external payable {}
}

