contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        bool emergency,
        uint256 amount,
        uint256 unlockTime,
        address asset,
        bool assetBurnable,
        uint256 suppliedAmount,
        bool hasApproval,
        bool governanceApproved,
        bool shouldRevertAfterFail
    ) public payable {
        // Preconditions: we need the supplied amount to match the configured flash amount
        require(suppliedAmount > 0, "test: zero amount");
        require(assetBurnable == false, "test: burnable simplifies test");
        // The DAO must exist and be callable
        require(address(c.DAO()) != address(0), "test: no DAO");

        // Setup: configure flash governance as this test contract
        c.configureFlashGovernance(asset, suppliedAmount, unlockTime, assetBurnable);
        c.configureSecurityParameters(1, 1, 10);

        // Read initial balance of this contract for the asset
        uint256 balanceBefore = c.pendingFlashDecision(address(this), address(this)).amount;

        // Create a policy that requires approval
        c.setGoverned(address(this), true);

        // Depending on input, either approve or not approve; also try a failing path first
        if (!hasApproval) {
            c.setEnforcement(true);
            c.assertGovernanceApproved(address(this), address(this), emergency);
        } else {
            c.setEnforcement(false);
            c.assertGovernanceApproved(address(this), address(this), emergency);
        }

        // Read the pending decision recorded by the successful call
        (uint256 recordedAmount, uint256 recordedUnlockTime, address recordedAsset, ) = c.pendingFlashDecision(
            address(this),
            address(this)
        );

        // The unlock time is always block.timestamp + configured unlockTime
        assert(recordedUnlockTime == block.timestamp + unlockTime);

        // The recorded asset must match only if an actual transfer was made
        // If no approval, governance call reverts, but in our simplified environment we
        // just ensure that a successful call means the asset and amount match expectations.
        assert(recordedAsset == asset || recordedAmount == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 amount,
        uint256 unlockTime,
        address asset,
        bool assetBurnable,
        bool emergency
    ) public payable {
        // The flash governance must have been configured with a nonzero asset and amount
        require(amount > 0, "test: zero amount");
        require(asset != address(0), "test: zero asset");
        require(address(c.DAO()) != address(0), "test: no DAO");

        // Configure flash governance as this test contract (msg.sender is InvMutTest)
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Make the test contract a governed address so assertGovernanceApproved is allowed
        address[] memory governables = new address[](1);
        bool[] memory isGoverned = new bool[](1);
        governables[0] = address(this);
        isGoverned[0] = true;
        c.setGoverned(governables, isGoverned);

        // Setup security parameters to enable flash governance in this epoch
        c.configureSecurityParameters(1, 0, 10);

        // Attempt the governance approval; may revert if transferFrom fails
        bool reverted;
        try c.assertGovernanceApproved(address(this), address(this), emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            (uint256 recordedAmount, uint256 recordedUnlockTime, address recordedAsset, ) = c.pendingFlashDecision(
                address(this),
                address(this)
            );
            assert(
                recordedAmount == amount &&
                recordedAsset == asset &&
                recordedUnlockTime == block.timestamp + unlockTime
            );
        } else {
            // On revert, no state change should have occurred; the pending decision remains zeroed
            (uint256 recordedAmount, uint256 recordedUnlockTime, address recordedAsset, ) = c.pendingFlashDecision(
                address(this),
                address(this)
            );
            assert(recordedAmount == 0 && recordedUnlockTime == 0 && recordedAsset == address(0));
        }
    }

    receive() external payable {}
}

