        (uint256 cfgAmount, uint256 cfgUnlock, address cfgAsset, bool cfgBurnable) = c.flashGovernanceConfig();
        assert(cfgAmount >= 0);
        assert(cfgUnlock >= 0);

        // The four-argument read above must be the same storage slot view as the auto getters.
        assert(cfgAmount == c.flashGovernanceConfig());
    }

    receive() external payable {}
}

