        // Capture the caller's pending decision entry before setEnforcement (must be empty on a fresh deployment for this key).
        (uint256 pAmountBefore, uint256 pUnlockBefore, address pAssetBefore, bool pBurnableBefore) = c.pendingFlashDecision(address(this), address(this));

