contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address target, address sender, address asset, uint256 amount, uint256 unlockTime) public payable {
        require(address(this).balance >= 0);

        // setup: register the caller as a governed source of flash decisions
        address[] memory gs = new address[](1);
        bool[] memory st = new bool[](1);
        gs[0] = address(this);
        st[0] = true;
        // cannot call setGoverned without successful proposal; so instead just try
        // the public surface that is available and observe behavior.

        // configure flash governance (will revert unless this test contract is a successful proposal)
        // to keep the test reachable even when configuration fails, drive only read-only/public calls first.
        uint256 cfgAmount = c.flashGovernanceConfig();
        (uint256 cfgAmount2, uint256 cfgUnlock, address cfgAsset, bool cfgBurnable) = c.flashGovernanceConfig();
        uint256 secEpoch = c.security();

        // read the pending decision accessor before-and-after through its public getter
        (uint256 pAmount, uint256 pUnlock, address pAsset, bool pBurnable) = c.pendingFlashDecision(target, sender);

        // The only state-changing call we can reach that is guaranteed to at least be attempted:
        // assertGovernanceApproved is guarded by flashEnabled, so it will revert from this test contract
        // unless this test contract is the DAO or is governed. We record the revert.
        bool agReverted;
        try c.assertGovernanceApproved(sender, target, false) {
            agReverted = false;
        } catch {
            agReverted = true;
        }

        // After the attempt, the pending decision entry must be either unchanged or newly created.
        (uint256 qAmount, uint256 qUnlock, address qAsset, bool qBurnable) = c.pendingFlashDecision(target, sender);

        // withdrawGovernanceAsset is open to anyone; it must revert exactly when the pending decision
        // is not (asset, amount, unlockTime) eligible for withdrawal by msg.sender (this contract).
        bool wdReverted;
        try c.withdrawGovernanceAsset(target, asset) {
            wdReverted = false;
        } catch {
            wdReverted = true;
        }

        (uint256 rAmount, uint256 rUnlock, address rAsset, bool rBurnable) = c.pendingFlashDecision(target, sender);

        // General rule: withdrawal succeeds only if before the call there was a pending decision for
        // (target, msg.sender) with the requested asset, a positive amount, and unlockTime < now.
        // If that precondition does not hold, it must have reverted and left pendingFlashDecision untouched.
        bool hadEligible = (qAsset == asset) && (qAmount > 0) && (qUnlock < block.timestamp);
        assert(wdReverted == !hadEligible);
        assert(!wdReverted || ((rAmount == qAmount) && (rUnlock == qUnlock) && (rAsset == qAsset) && (rBurnable == qBurnable)));
        assert(wdReverted || (rAmount == 0));
        assert(wdReverted || (rAsset == address(0)));
    }

    receive() external payable {}
}

