contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address targetContract, address asset, uint256 amount) public payable {
        require(true);

        address sender = address(this);

        // Read before-state
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) = c.pendingFlashDecision(targetContract, sender);

        // Call withdrawGovernanceAsset and record whether it reverted
        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if there was no pending decision (amount == 0), the call must revert.
        // Also, if there was a pending decision with an asset equal to the provided asset and amount > 0
        // and unlockTime < block.timestamp, the call must NOT revert.
        // We only assert the first implication to make it a general rule over all inputs.
        if (beforeAmount == 0) {
            assert(reverted);
        } else {
            // If there is a pending decision, the call should revert only if asset mismatches or unlockTime >= block.timestamp
            if (beforeAsset != asset || beforeUnlockTime >= block.timestamp) {
                assert(reverted);
            } else {
                assert(!reverted);
            }
        }
    }

    receive() external payable {}
}

