    constructor(C _c) { c = _c; }

    function run(
        address dao,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable
    ) public {
        c.setDAO(dao);
        c.endConfiguration();
        uint256 priorAssetBefore = uint256(uint160(address(0)));
        uint256 priorAmountBefore = 0;
        try c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable) {
            (uint256 cfgAmount, uint256 cfgUnlockTime, address cfgAsset, bool cfgBurnable) = c.flashGovernanceConfig();
            assert(
                cfgAmount == amount &&
                cfgUnlockTime == unlockTime &&
                cfgAsset == asset &&
                cfgBurnable == assetBurnable
            );
        } catch {
            (uint256 cfgAmount, uint256 cfgUnlockTime, address cfgAsset, bool cfgBurnable) = c.flashGovernanceConfig();
            assert(
                (cfgAmount == priorAssetBefore) &&
                (cfgUnlockTime == priorAmountBefore) &&
                (cfgAsset == address(0)) &&
                (cfgBurnable == false)
            );
        }
    }
}

