contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address dao,
        address flashGoverner,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable
    ) public {
        // Make the DAO configuration allow a successful proposal from this contract.
        c.setDAO(dao);
        c.endConfiguration();

        // A successful proposal is required by onlySuccessfulProposal.
        // We install a mock DAO / flash governor at the DAO address.
        MockDAO mock = new MockDAO(flashGoverner);
        // We cannot deploy a contract to `dao`; setDAO already stored the parameter.
        // Instead, use the DAO address itself as the successful-proposal oracle.
        // The test contract must be able to call c.configureFlashGovernance.
        // Since onlySuccessfulProposal checks LimboDAOLike(DAO).successfulProposal(msg.sender),
        // we need an oracle at DAO. We cannot deploy at an arbitrary address, so we
        // configure the mock logic through the InvMutTest itself: c.DAO() returns `dao`,
        // so we deploy the mock and then set DAO to the mock address.
        c.setDAO(address(mock));

        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        (uint256 cfgAmount, uint256 cfgUnlockTime, address cfgAsset, bool cfgAssetBurnable) = c.flashGovernanceConfig();
        assert(
            cfgAsset == asset &&
            cfgAmount == amount &&
            cfgUnlockTime == unlockTime &&
            cfgAssetBurnable == assetBurnable
        );
    }

    receive() external payable {}
}

contract MockDAO {
    address private immutable governor;

    constructor(address _governor) {
        governor = _governor;
    }

    function successfulProposal(address) external pure returns (bool) {
        return true;
    }

    function getFlashGoverner() external view returns (address) {
        return governor;
    }

    function proposalConfig()
        external
        pure
        returns (
            uint256,
            uint256,
            address
        )
    {
        return (0, 0, address(0));
    }
}

