contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public payable {
        // A fresh C is not yet configured, and its DAO has no successful proposal for msg.sender,
        // so configureFlashGovernance would always revert with "EJ".
        // We only assert the rule when the call can actually be driven.
        bool reverted;
        try c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 gotAmount, uint256 gotUnlockTime, address gotAsset, bool gotBurnable) = c.flashGovernanceConfig();

        if (reverted) {
            assert(gotAmount == 0 && gotUnlockTime == 0 && gotAsset == address(0) && gotBurnable == false);
        } else {
            assert(gotAsset == asset && gotAmount == amount && gotUnlockTime == unlockTime && gotBurnable == assetBurnable);
        }
    }

    receive() external payable {}
}

