contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        address target,
        address sender,
        bool emergency
    ) public {
        require(asset != address(0), "asset zero");
        require(amount > 0, "amount zero");
        require(sender != address(0), "sender zero");

        // Make DAO equal to this test contract so that flashEnabled permits msg.sender == DAO
        c.setDAO(address(this));
        c.endConfiguration();

        // Configure the flash governance parameters; caller (this contract) must be the DAO
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Seed the security parameters so that an epoch check exists (still need emergency or enough time elapsed)
        c.configureSecurityParameters(1, uint256(1), uint8(1));

        // Read back the configured public fields to know the exact before values
        address cfgAsset = c.flashGovernanceConfig().asset();
        uint256 cfgAmount = c.flashGovernanceConfig().amount();
        uint256 cfgUnlockTime = c.flashGovernanceConfig().unlockTime();
        bool cfgBurnable = c.flashGovernanceConfig().assetBurnable();

        // The approval call is from the DAO (this contract), so it is flash permitted and
        // should succeed provided the token transferFrom does not revert (which depends on
        // the asset contract) and pending unlockTime < block.timestamp.  We use emergency=true
        // to avoid epoch restrictions entirely, so the only failure point is the token transfer.
        require(IERC20(cfgAsset).balanceOf(sender) >= cfgAmount, "sender token balance insufficient");
        require(IERC20(cfgAsset).allowance(sender, address(c)) >= cfgAmount, "sender allowance insufficient");
        IERC20(cfgAsset).transferFrom(sender, address(this), cfgAmount);
        IERC20(cfgAsset).approve(address(c), cfgAmount);

        (address rAsset, uint256 rAmount, uint256 rUnlockTime, bool rBurnable) = c.pendingFlashDecision(target, sender);
        // The mapping entry is initially empty; after a successful call it should match the config

        uint256 expectedUnlock = c.flashGovernanceConfig().unlockTime();

        c.assertGovernanceApproved{gas: 200000}(sender, target, emergency);

        (address aAsset, uint256 aAmount, uint256 aUnlockTime, bool aBurnable) = c.pendingFlashDecision(target, sender);

        // General rule: after a successful approval, the stored pending decision must have exactly
        // the configured asset, amount, and burnable flag, and its unlockTime must equal the
        // configured unlock time plus the timestamp at which the approval was executed.
        assert(
            aAsset == cfgAsset &&
            aAmount == cfgAmount &&
            aBurnable == cfgBurnable &&
            aUnlockTime >= cfgUnlockTime &&
            aUnlockTime - cfgUnlockTime <= block.timestamp
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        address target,
        address sender,
        bool emergency
    ) public {
        require(asset != address(0), "asset zero");
        require(amount > 0, "amount zero");
        require(sender != address(0), "sender zero");
        require(target != address(0), "target zero");

        // Make DAO equal to this test contract so flashEnabled permits msg.sender == DAO
        c.setDAO(address(this));
        c.endConfiguration();

        // Configure flash governance parameters; caller (this contract) is the DAO
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Seed security parameters so that epoch check exists
        c.configureSecurityParameters(1, 1, 1);

        // Read back configured state (public getters of public state variables)
        (uint256 cfgAmount, uint256 cfgUnlockTime, address cfgAsset, bool cfgBurnable) = c.flashGovernanceConfig();

        // Ensure the sender (this contract) has enough token balance and allowance is not needed
        // since transferFrom(sender, address(this), ...) is called by c on behalf of this contract,
        // msg.sender for the token is address(c), so we need balance and allowance for c.
        require(IERC20(cfgAsset).balanceOf(address(this)) >= cfgAmount, "insufficient balance");
        IERC20(cfgAsset).approve(address(c), cfgAmount);

        uint256 beforeTimestamp = block.timestamp;

        // The approval call from DAO; use emergency=true to bypass epoch restrictions
        c.assertGovernanceApproved(sender, target, emergency || true);

        (uint256 aAmount, uint256 aUnlockTime, address aAsset, bool aBurnable) = c.pendingFlashDecision(target, sender);

        // General rule: stored decision matches config except unlockTime = cfgUnlockTime + timestamp
        assert(
            aAsset == cfgAsset &&
            aAmount == cfgAmount &&
            aBurnable == cfgBurnable &&
            aUnlockTime == cfgUnlockTime + beforeTimestamp
        );
    }

    receive() external payable {}
}

