        governables[0] = address(this);
        isGoverned[0] = true;
        c.setGoverned(governables, isGoverned);
        c.assertGovernanceApproved(sender2, targetContract, emergency);
        (uint256 pendingAmountBefore, uint256 pendingUnlockBefore) = (0, 0);
        (pendingAmountBefore, pendingUnlockBefore) = c.pendingFlashDecision(targetContract, sender2);
