    constructor(C _c) {
        c = _c;
    }

    function run(address attacker, address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public {
        // read the before state of the public flashGovernanceConfig getters
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeAssetBurnable) = c.flashGovernanceConfig();

        // attacker is this test contract; try to configure governance directly
        bool reverted;
        try c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read the after state
        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterAssetBurnable) = c.flashGovernanceConfig();

        // The rule: if the call reverted, the config must be unchanged; if it did not revert,
        // then the config must match the new parameters (which can only happen for a successful proposal).
        assert(
            reverted
                ? (afterAmount == beforeAmount &&
                   afterUnlockTime == beforeUnlockTime &&
                   afterAsset == beforeAsset &&
                   afterAssetBurnable == beforeAssetBurnable)
                : (afterAmount == amount &&
                   afterUnlockTime == unlockTime &&
                   afterAsset == asset &&
                   afterAssetBurnable == assetBurnable)
        );
    }
}

