    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address dao,
        uint256 pendingAmount,
        uint256 pendingUnlockTime,
        bool pendingAssetBurnable,
        address decisionTarget,
        bool emergency,
        uint256 epochSize,
        bool registerAsGoverned
    ) public {
        c.setDAO(dao);

        address[] memory governables = new address[](1);
        governables[0] = address(this);
        bool[] memory isGoverned = new bool[](1);
        isGoverned[0] = registerAsGoverned;
        c.setGoverned(governables, isGoverned);

        (bool okConfig,) = address(c).call(
            abi.encodeWithSignature(
                "configureFlashGovernance(address,uint256,uint256,bool)",
                address(0xdead), pendingAmount, pendingUnlockTime, pendingAssetBurnable
            )
        );
        require(!okConfig, "setup: flash governance should not be configurable without proposal");

        (uint256 s0, uint256 s1, uint8 s2, uint8 s3) = c.security();
        require(s0 == s1, "setup: security defaults differ");
        require(s2 == s3, "setup: security defaults differ");

        (bool okCall, ) = address(c).call(
            abi.encodeWithSignature(
                "assertGovernanceApproved(address,address,bool)",
                address(this), decisionTarget, emergency
            )
        );

        (bool decisionAssetIsSet, ) = address(c).staticcall(
            abi.encodeWithSignature("pendingFlashDecision(address,address)", decisionTarget, address(this))
        );
        require(decisionAssetIsSet, "read: pendingFlashDecision should be readable");

        assert(!okCall);
    }
}

