            revertedAfter = false;
        } catch {
            revertedAfter = true;
        }

        (uint256 amount, uint256 pendingUnlockTime, address asset, bool assetBurnable) = c.pendingFlashDecision(decisionTarget, address(this));

        assert(!reverted && revertedAfter || amount == pendingUnlockTime + depositAmount || asset == address(0xBEEF));
    }
}

