contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address setupSender,
        address target,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        address withdrawTarget,
        address withdrawAsset
    ) public payable {
        // Set up a pending decision for (withdrawTarget, setupSender).
        // configureFlashGovernance is only callable via onlySuccessfulProposal by msg.sender = DAO.
        // DAO was set to address(this) in the constructor of C, so this contract is the DAO.
        require(setupSender != withdrawTarget || asset != withdrawAsset || true);

        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // Approve and create a pending flash decision for setupSender.
        // Need to give c the tokens: approve c to transfer amount from this test contract.
        // asset is an IERC20; call approve directly on it (not on c).
        // We don't have an interface, but IERC20 already exists in the compilation unit.
        IERC20(asset).approve(address(c), amount);

        c.assertGovernanceApproved(setupSender, target, true);

        // Capture before values via public getters.
        (
            uint256 beforeAmount,
            uint256 beforeUnlock,
            address beforeAsset,
            bool beforeBurnable
        ) = c.pendingFlashDecision(target, setupSender);

        uint256 beforeBal = IERC20(asset).balanceOf(address(this));

        // Try withdraw for (withdrawTarget, withdrawSender) where withdrawSender is the configured sender.
        // The pending entry is keyed by (target, sender). withdrawGovernanceAsset uses (targetContract, msg.sender),
        // so msg.sender here (this contract) must equal the setup sender for the entry to match.
        bool reverted;
        try c.withdrawGovernanceAsset(withdrawTarget, withdrawAsset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values.
        (
            uint256 afterAmount,
            uint256 afterUnlock,
            address afterAsset,
            bool afterBurnable
        ) = c.pendingFlashDecision(target, setupSender);

        uint256 afterBal = IERC20(asset).balanceOf(address(this));

        // General rule: withdraw succeeds (no revert) iff the caller has a pending decision with matching
        // key (withdrawTarget, msg.sender == setupSender), matching asset, positive amount, and unlocked.
        // Since setupSender is the caller (this contract is msg.sender for all c calls in this test,
        // and withdrawTarget is compared to target), the condition reduces to (withdrawTarget == target) &&
        // (withdrawAsset == beforeAsset) && (beforeAmount > 0) && (beforeUnlock < block.timestamp).
        // Also, when it succeeds, the pending entry is deleted and the asset is transferred.
        bool preCondition =
            withdrawTarget == target &&
            withdrawAsset == beforeAsset &&
            beforeAmount > 0 &&
            beforeUnlock < block.timestamp;

        assert(
            (!reverted == preCondition) &&
            (reverted || afterAmount == 0) &&
            (reverted || afterAsset == address(0)) &&
            (reverted || afterUnlock == 0) &&
            (reverted || afterBal == beforeBal + beforeAmount)
        );
    }

    receive() external payable {}
}

