contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address sender,
        address target,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable
    ) public payable {
        // Setup: configure the flash governance config.
        // setGoverned / configureFlashGovernance are onlySuccessfulProposal.
        // Effectively configured is false in a fresh contract, so these should
        // pass for any sender per the Governable logic.
        address[] memory governables = new address[](1);
        governables[0] = address(this);
        bool[] memory isGoverned = new bool[](1);
        isGoverned[0] = true;
        c.setGoverned(governables, isGoverned);

        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Make the first pending decision. This requires an ERC20 transferFrom from
        // this contract to c, so we must have approved c and hold enough of asset.
        // Since we can't know asset's interface details, we set up via standard IERC20 calls.
        // Precondition: asset must be a real ERC20 where this contract can approve and transfer.
        // To keep the property meaningful and reachable, require amount > 0 and that an
        // approval succeeds, then make the first call.
        require(amount > 0, "amount must be positive");

        // First call should succeed if the state is fresh and tolerance is satisfied
        // (security.epochSize default 0 and lastFlashGovernanceAct default 0,
        //  so block.timestamp - 0 > 0 is true for block.timestamp > 0).
        // We approve and call; if the call reverts we can't test the second call below,
        // so we use try/catch and assert the general rule only when the first call succeeded.
        bool firstSucceeded;
        try {
            IERC20(asset).approve(address(c), amount);
        } catch {}

        try c.assertGovernanceApproved(sender, target, false) {
            firstSucceeded = true;
        } catch {
            firstSucceeded = false;
        }

        // Now read the pending decision stored by c.
        (uint256 pAmount, uint256 pUnlockTime, address pAsset, bool pBurnable) =
            c.pendingFlashDecision(target, sender);

        // Read security lastFlashGovernanceAct before second call.
        (uint256 epochSize, uint256 lastAct, uint8 maxChange, uint8 tolerance) = c.security();

        bool secondReverted;
        try c.assertGovernanceApproved(sender, target, false) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        (uint256 pAmountAfter, uint256 pUnlockTimeAfter, address pAssetAfter, bool pBurnableAfter) =
            c.pendingFlashDecision(target, sender);

        // General rule: if a pending decision exists with unlockTime in the future,
        // a second call from the same sender/target must revert and must not alter
        // the stored pending decision.
        assert(
            !firstSucceeded ||
                pUnlockTime <= block.timestamp ||
                (secondReverted &&
                    pAmountAfter == pAmount &&
                    pUnlockTimeAfter == pUnlockTime &&
                    pAssetAfter == pAsset &&
                    pBurnableAfter == pBurnable)
        );
    }

    receive() external payable {}
}

