    function run(uint256 amount) public {
        // Need a real token to exercise the transferFrom success path; use a minimal in-test ERC20 via assembly creation?
        // No new deployments allowed. Instead use a payable-less simple token? Cannot declare contracts.
        // So we choose a path that doesn't need extra contracts: call assertGovernanceApproved and observe revert,
        // but the rule must be about guaranteed state change. Use withdrawGovernanceAsset revert rule instead.
        // Actually assertGovernanceApproved requires flashGovernanceConfig.asset to be an ERC20.
        // Without a helper contract, we cannot create one. Use the revert-on-missing-pending rule.
        (uint256 beforeAmount, uint256 beforeUnlock, address beforeAsset, bool beforeBurnable) = c.flashGovernanceConfig();
        (uint256 beforeEpochSize, uint256 beforeLastAct, uint8 beforeMaxChange, uint8 beforeTolerance) = c.security();

        bool reverted;
        try c.withdrawGovernanceAsset(address(this), address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 afterAmount, uint256 afterUnlock, address afterAsset, bool afterBurnable) = c.flashGovernanceConfig();
        (uint256 afterEpochSize, uint256 afterLastAct, uint8 afterMaxChange, uint8 afterTolerance) = c.security();

        // The general rule: withdrawing an unpending flash governance asset must revert and must not disturb config/security state.
        assert(
            reverted &&
            afterAmount == beforeAmount &&
            afterUnlock == beforeUnlock &&
            afterAsset == beforeAsset &&
            afterBurnable == beforeBurnable &&
            afterEpochSize == beforeEpochSize &&
            afterLastAct == beforeLastAct &&
            afterMaxChange == beforeMaxChange &&
            afterTolerance == beforeTolerance
        );
    }
}

