contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address targetContract, address asset) public {
        require(true);
        address sender = address(this);

        // Setup: create a pending flash decision for this test contract so that
        // some entry exists, then withdraw it so that the sender's entry is cleared.
        c.setGoverned(sender, true);
        c.configureFlashGovernance(asset, 100, 1000, false);
        c.assertGovernanceApproved(sender, targetContract, false);

        // Capture the asset and amount from the pending entry before withdrawing.
        address beforeAsset;
        uint256 beforeAmount;
        (beforeAsset, beforeAmount, , ) = c.pendingFlashDecision(targetContract, sender);

        // Consume the entry so it is no longer pending for the sender.
        c.withdrawGovernanceAsset(targetContract, asset);

        // Now attempt to withdraw again with no pending decision; it must revert.
        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the failed withdrawal, the entry must still be cleared: asset and
        // amount must be zero. The pre-existing entry was fully consumed, so the
        // revert must not have restored it or altered it.
        address afterAsset;
        uint256 afterAmount;
        (afterAsset, afterAmount, , ) = c.pendingFlashDecision(targetContract, sender);

        assert(reverted && afterAsset == address(0) && afterAmount == 0 && beforeAmount > 0);
    }

    receive() external payable {}
}

