        // which requires the caller to implement configured(). Since we cannot satisfy that,
        // we cannot observe the flag change of an arbitrary address.
        // Therefore, choose a rule that does not depend on reading enforceLimitsActive.

        // Fall back to a different property: setEnforcement is callable by anyone and
        // never reverts. We can assert that after calling it, the contract is still
        // responsive (e.g., configured getter unchanged) and no state corruption occurred.

        // However, to keep close to the original intent, we can test that
        // setGoverned only affects the governed mapping, which is public.

        address[] memory governables = new address[](1);
        bool[] memory isGoverned = new bool[](1);
        governables[0] = other;
        isGoverned[0] = enforce;

        // setGoverned requires onlySuccessfulProposal, which will revert because
        // the caller is not a successful proposal.
        bool reverted;
        try c.setGoverned(governables, isGoverned) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: setGoverned must revert when called by a non-proposal address.
        assert(reverted);
    }

    receive() external payable {}
}

