    }

    function run(
        address[] calldata governables,
        bool[] calldata isGoverned,
        address probe
    ) public payable {
        require(governables.length == isGoverned.length, "lengths must match");
        bool[] memory beforeValues = new bool[](governables.length);
        for (uint256 i = 0; i < governables.length; i++) {
            beforeValues[i] = c.governed(governables[i]);
        }
        bool reverted;
        try c.setGoverned(governables, isGoverned) {
            reverted = false;
        } catch {
            reverted = true;
        }
        for (uint256 i = 0; i < governables.length; i++) {
            if (governables[i] == probe) {
                assert(
                    (reverted && c.governed(probe) == beforeValues[i]) ||
                    (!reverted && c.governed(probe) == isGoverned[i])
                );
                return;
            }
        }
        if (reverted) {
            assert(true);
        } else {
            assert(c.governed(probe) == false || c.governed(probe) == true);
        }
    }

    receive() external payable {}
}

