contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address dao, address asset, uint256 amount, uint256 unlockTime, bool assetBurnable)
        public
    {
        // Ensure the caller is not the DAO and has not been marked as governed.
        require(msg.sender != dao, "caller must not be DAO");

        // Capture existing config so we can distinguish a change from a no-change.
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) = c.flashGovernanceConfig();

        bool reverted;
        try c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterBurnable) = c.flashGovernanceConfig();

        // The flash governance config may only change if the call succeeded;
        // a failed call must leave it untouched, and a successful call sets exactly the supplied values.
        if (reverted) {
            assert(afterAmount == beforeAmount && afterUnlockTime == beforeUnlockTime && afterAsset == beforeAsset && afterBurnable == beforeBurnable);
        } else {
            assert(afterAmount == amount && afterUnlockTime == unlockTime && afterAsset == asset && afterBurnable == assetBurnable);
        }
    }
}

