contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        address governable,
        bool isGoverned
    ) public {
        // Precondition: governable must not be zero to avoid issues with calling setGoverned
        require(governable != address(0), "zero governable");

        // Record initial flash governance config (before any state-changing call)
        // The getter returns (amount, unlockTime, asset, assetBurnable)
        (uint256 initAmount, uint256 initUnlock, address initAsset, bool initBurnable) = c.flashGovernanceConfig();

        // Try to change governed status without a successful proposal - this should revert
        address[] memory governables = new address[](1);
        governables[0] = governable;
        bool[] memory statuses = new bool[](1);
        statuses[0] = isGoverned;

        bool reverted;
        try c.setGoverned(governables, statuses) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, the flashGovernanceConfig must be unchanged
        (uint256 newAmount, uint256 newUnlock, address newAsset, bool newBurnable) = c.flashGovernanceConfig();

        // The rule: either the call reverted (and config unchanged), or it succeeded (config also unchanged
        // because setGoverned does not modify flashGovernanceConfig).
        // Additionally, if it succeeded, the governed mapping must have been updated.
        assert(
            newAmount == initAmount &&
            newUnlock == initUnlock &&
            newAsset == initAsset &&
            newBurnable == initBurnable &&
            (reverted || c.governed(governable) == isGoverned)
        );
    }

    receive() external payable {}
}

