            received = 0;
        }

        uint256 testBalanceAfter = IERC20(asset).balanceOf(address(this));
        uint256 contractBalanceAfter = IERC20(asset).balanceOf(address(c));

        bool recordedPending = storedAssetBefore == asset && storedAmountBefore > 0 && storedUnlockBefore < block.timestamp;

        if (recordedPending) {
            assert(!reverted && received == storedAmountBefore && (contractBalanceAfter + received == contractBalanceBefore));
        } else {
            assert(reverted && testBalanceAfter == testBalanceBefore && contractBalanceAfter == contractBalanceBefore);
        }
    }

