contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, address user, address asset, uint256 amount, uint256 unlockTime) public payable {
        require(target != address(0), "target");
        require(user == address(this), "user must be this");
        require(asset != address(0), "asset");
        require(amount > 0, "amount");

        // The mapping getter returns a tuple (amount, unlockTime, asset, assetBurnable).
        uint256 beforeAmount;
        uint256 beforeUnlockTime;
        address beforeAsset;
        bool beforeBurnable;
        (beforeAmount, beforeUnlockTime, beforeAsset, beforeBurnable) = c.pendingFlashDecision(target, user);

        // A call to withdrawGovernanceAsset must revert when no pending decision exists.
        bool reverted;
        try c.withdrawGovernanceAsset(target, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterAmount;
        uint256 afterUnlockTime;
        address afterAsset;
        bool afterBurnable;
        (afterAmount, afterUnlockTime, afterAsset, afterBurnable) = c.pendingFlashDecision(target, user);

        // The general rule: the pending state of any (target, user) pair is either untouched or fully deleted;
        // and when the pair is empty (amount == 0), withdrawGovernanceAsset always reverts.
        assert(
            (beforeAmount == afterAmount && beforeUnlockTime == afterUnlockTime && beforeAsset == afterAsset) ||
                (afterAmount == 0 && afterUnlockTime == 0 && afterAsset == address(0)) ||
                (beforeAmount == 0
                    ? reverted
                    : (beforeUnlockTime < block.timestamp && beforeAsset == asset ? reverted == false : reverted))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, address asset) public payable {
        require(target != address(0), "target");
        require(asset != address(0), "asset");

        // Read pending decision for (target, msg.sender).
        uint256 beforeAmount;
        uint256 beforeUnlockTime;
        address beforeAsset;
        bool beforeBurnable;
        (beforeAmount, beforeUnlockTime, beforeAsset, beforeBurnable) = c.pendingFlashDecision(target, address(this));

        uint256 balBefore = address(this).balance;

        bool reverted;
        try c.withdrawGovernanceAsset(target, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterAmount;
        uint256 afterUnlockTime;
        address afterAsset;
        bool afterBurnable;
        (afterAmount, afterUnlockTime, afterAsset, afterBurnable) = c.pendingFlashDecision(target, address(this));

        uint256 balAfter = address(this).balance;

        // General rule: the pending decision entry is all-or-nothing.
        // Either the call reverts and nothing changed, or it succeeds,
        // the entry is deleted, and value moved to this contract by the entry's amount.
        if (beforeAmount == 0) {
            assert(reverted);
            assert(afterAmount == 0 && afterUnlockTime == 0 && afterAsset == address(0));
        } else {
            if (reverted) {
                assert(afterAmount == beforeAmount && afterUnlockTime == beforeUnlockTime && afterAsset == beforeAsset);
            } else {
                assert(afterAmount == 0 && afterUnlockTime == 0 && afterAsset == address(0));
                assert(balAfter >= balBefore);
            }
        }
    }

    receive() external payable {}
}

