contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, address user, address asset, uint256 amount) public {
        // Configure DAO to be the caller so the onlySuccessfulProposal modifier passes.
        c.setDAO(address(this));

        // Configure flash governance asset/amount/unlockTime. OnlySuccessfulProposal is bypassed
        // because configured is false and msg.sender == DAO.
        c.configureFlashGovernance(asset, amount, 0, true);

        // Create unsettled pending state for (target, user).
        c.assertGovernanceApproved(user, target, true);

        // Attempt the deciding call: burn the flash governance asset. It is expected to succeed
        // (no revert) under the successful-proposal bypass and should delete the pending entry.
        bool reverted;
        try c.burnFlashGovernanceAsset(target, user, asset, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The deciding call must succeed and the pending flash decision must no longer be withdrawable.
        bool withdrawReverted;
        try c.withdrawGovernanceAsset(target, asset) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        assert(!reverted && withdrawReverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, address user, address asset, uint256 amount) public {
        // Make msg.sender (this test contract) the DAO, so onlySuccessfulProposal can pass
        // after configuration. setDAO is allowed because DAO is initially the constructor DAO
        // and configured is false.
        c.setDAO(address(this));

        // Configure a burnable flash governance asset so the pending decision can be created
        // and then burned away by burnFlashGovernanceAsset.
        c.configureFlashGovernance(asset, amount, 0, true);

        // Create unsettled pending state for (target, user).
        c.assertGovernanceApproved(user, target, true);

        // Read the before-state through the public getter: the pending entry must be settled
        // (non-zero amount) for the rule to be meaningful.
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) =
            c.pendingFlashDecision(target, user);

        // Deciding call: a successful-proposal burn deletes the pending decision.
        bool burnReverted;
        try c.burnFlashGovernanceAsset(target, user, asset, amount) {
            burnReverted = false;
        } catch {
            burnReverted = true;
        }

        // After the delete, withdrawal for the same target/user/asset must revert.
        bool withdrawReverted;
        try c.withdrawGovernanceAsset(target, asset) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // General rule: whenever burnFlashGovernanceAsset succeeds on a target/user whose
        // pending entry actually existed, the pending entry is deleted, so a subsequent
        // withdrawGovernanceAsset for that same target/user/asset cannot succeed.
        assert(
            !burnReverted || beforeAmount == 0 || withdrawReverted
        );
    }

    receive() external payable {}
}

